window.RiriGraph={updateNotes:(id,value)=>{const next=id==null?window.PlanNotes.plan(value):window.PlanNotes.node(value);commit(()=>{if(id==null)g.planNotes=next;else {const n=g.nodes.find(n=>n.id===id);if(!n)throw Error('노드를 찾을 수 없습니다.');n.constructionNotes=next;}});},isShared:()=>sharedSession,saveShared:()=>{sharedSession=false;save();return true;},loadShared:v=>{const nextD=v.dataMode==='vanilla'?window.VANILLA_DATA:window.SF_DATA.sfplus,next=M.validate(v,nextD);M.solve(next,nextD);snapshot();sharedSession=true;d=nextD;g=next;pending=null;selected.clear();render();},apply:v=>{loadValue(v);return g;},setMode:switchMode,data:()=>d,get:()=>JSON.parse(JSON.stringify(g)),load:loadValue,render,fit:(options={})=>{fit(options.all===true);render();},display:()=>JSON.parse(JSON.stringify(display)),result:()=>JSON.parse(JSON.stringify(result)),menu:generalMenu};
window.PlanNotes.mount(window.RiriGraph);
